module pulp_clock_mux2
  (
   input  logic clk0_i,
   input  logic clk1_i,
   input  logic clk_sel_i,
   output logic clk_o
   );
always_comb
      begin
         if(clk_sel_i == 1'b0)
            clk_o = clk0_i;
         else
            clk_o = clk1_i;
      end
endmodule

module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] count;
    reg tick;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            tick <= 0;
        end else begin
            if (count == div - 1) begin
                count <= 0;
                tick <= 1;
            end else begin
                count <= count + 1;
                tick <= 0;
            end
        end
    end
endmodule

module addmulxor_1_stage_unsigned_9_bit_xor_reduction(
