	input  [8:0] b,
	input  [8:0] c,
	input  [8:0] d,
	output [8:0] out,
	input clk);
logic  [17:0] stage0;

	always @(posedge clk) begin
	stage0 <= ((d + a) * b) ^ c;
	end

	assign out = ^(stage0);
endmodule

module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]   count50   ;
        logic   [31:0]   count72   ;
        logic   [1:0]   led50   ;
        logic   [1:0]   led72   ;
        logic   [7:0]   pmod50   ;
        logic   [7:0]   pmod72   ;
        assign   led     = led50 | led72;
        assign   pmod     = pmod50 | pmod72;
        always_ff @(posedge clk50)
        begin
            if (count50 < COUNT_LIMIT)
            begin
                count50 <= count50 + 1;
                led50 <= count50[31:30];
            end
        end
        always_ff @(posedge clk72)
        begin
            if (count72 < COUNT_LIMIT)
            begin
                count72 <= count72 + 1;
                led72 <= count72[31:30];
            end
        end
        always_ff @(posedge clk50)
        begin
            if (count50[31] == 1'b1)
            begin
                pmod50 <= count50[31:24];
            end
        end
        always_ff @(posedge clk72)
        begin
            if (count72[31] == 1'b1)
            begin
                pmod72 <= count72[31:24];
            end
        end
    endmodule

