module top_properties (input logic clock, read, write, ready);
property read_write(clock, read, write, ready);
    @(posedge clock) if (read) if (write) $property_fail;
    @(posedge clock) if (write) if (read) $property_fail;
    @(posedge clock) if (write) if (ready) $property_pass;
    endproperty

    property write_ready(clock, write, ready);
    @(posedge clock) if (write) if (ready) $property_pass;
    @(posedge clock) if (write) if (ready) $property_fail;
    endproperty

    initial begin
        assert property (read_write(clock, read, write, ready)) else $error;
        assert property (write_ready(clock, write, ready)) else $error;
    end
endmodule

