module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0]   mem[0:DEPTH-1];
reg [31:0]        wr_ptr;
reg [31:0]        rd_ptr;
reg [31:0]        word_count;
reg                prog_full_p;
reg                full_p;
reg                empty_p;
reg                overflow_p;
reg                underflow_p;

assign data_o = mem[rd_ptr];

assign prog_full = (word_count == DEPTH) ? 1'b1 : 1'b0;
assign full = (word_count == DEPTH) ? 1'b1 : 1'b0;
assign empty = (word_count == 0) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset_p) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        word_count <= 0;
        prog_full_p <= 0;
        full_p <= 0;
        empty_p <= 0;
        overflow_p <= 0;
        underflow_p <= 0;
    end else begin
        if (data_we) begin
            if (word_count < DEPTH) begin
                mem[wr_ptr] <= data_i;
                wr_ptr <= wr_ptr + 1;
                word_count <= word_count + 1;
                prog_full_p <= 0;
                full_p <= 0;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end else begin
                overflow_p <= 1;
                underflow_p <= 0;
            end
        end else begin
            if (word_count > 0) begin
                rd_ptr <= rd_ptr + 1;
                word_count <= word_count - 1;
                prog_full_p <= 0;
                full_p <= 0;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end else begin
                overflow_p <= 0;
                underflow_p <= 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset_p) begin
        prog_full_p <= 0;
        full_p <= 0;
        empty_p <= 0;
    end else begin
        if (prog_full_p) begin
            if (word_count == PROG_FULL) begin
                prog_full_p <= 1;
                full_p <= 1;
                empty_p <= 0;
            end else begin
                prog_full_p <= 0;
                full_p <= 0;
                empty_p <= 0;
            end
        end else begin
            if (word_count == 0) begin
                prog_full_p <= 0;
                full_p <= 0;
                empty_p <= 1;
            end else begin
                prog_full_p <= 0;
                full_p <= 0;
                empty_p <= 0;
            end
        end
    end
end

endmodule

