module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
    );
parameter CLK_F = 32;
    reg [31:0] prescaler = 0;
    reg [31:0] counter = 0;
    always @(posedge CLK) begin
        if (prescaler == CLK_F - 1) begin
            prescaler <= 0;
            counter <= counter + 1;
        end else begin
            prescaler <= prescaler + 1;
        end
        if (counter == period) begin
            tone_out <= ~tone_out;
            counter <= 0;
        end
    end
endmodule

