module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0]   state;

always @(posedge clk or posedge reset) begin
    if (reset == 1'b1) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state   <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                if (s_valid == 1'b1) begin
                    data_p1 <= s_data;
                    state   <= 2'b01;
                end
            end
            2'b01: begin
                if (s_ready == 1'b1) begin
                    data_p2 <= s_data;
                    state   <= 2'b10;
                end
            end
            2'b10: begin
                if (m_ready == 1'b1) begin
                    m_data <= data_p2;
                    m_valid <= 1'b1;
                    state   <= 2'b00;
                end
            end
            default: begin
                m_data <= {N{1'b0}};
                m_valid <= 1'b0;
                state   <= 2'b00;
            end
        endcase
    end
end

assign s_ready = 1'b0;
assign m_valid = 1'b0;

endmodule

