module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(data_rs1, data_rs2, funct3) begin
	case (funct3)
		4'b0000: begin
			jmpb = (data_rs1 == data_rs2);
		end
		4'b0001: begin
			jmpb = (data_rs1 != data_rs2);
		end
		4'b0010: begin
			jmpb = (data_rs1 < data_rs2);
		end
		4'b0011: begin
			jmpb = (data_rs1 > data_rs2);
		end
		4'b0100: begin
			jmpb = (data_rs1 < 2'b00 && data_rs2 < 2'b00) || (data_rs1 < 2'b00 && data_rs2 > 2'b00) || (data_rs1 > 2'b00 && data_rs2 < 2'b00) || (data_rs1 > 2'b00 && data_rs2 > 2'b00);
		end
		4'b0101: begin
			jmpb = (data_rs1 > 2'b00 && data_rs2 < 2'b00) || (data_rs1 < 2'b00 && data_rs2 > 2'b00) || (data_rs1 < 2'b00 && data_rs2 < 2'b00) || (data_rs1 > 2'b00 && data_rs2 > 2'b00);
		end
		4'b0110: begin
			jmpb = (data_rs1 == data_rs2);
		end
		4'b0111: begin
			jmpb = (data_rs1 != data_rs2);
		end
		4'b1000: begin
			jmpb = (data_rs1 < data_rs2);
		end
		4'b1001: begin
			jmpb = (data_rs1 > data_rs2);
		end
		4'b1010: begin
			jmpb = (data_rs1 < 2'b00 && data_rs2 < 2'b00) || (data_rs1 < 2'b00 && data_rs2 > 2'b00) || (data_rs1 > 2'b00 && data_rs2 < 2'b00) || (data_rs1 > 2'b00 && data_rs2 > 2'b00);
		end
		4'b1011: begin
			jmpb = (data_rs1 > 2'b00 && data_rs2 < 2'b00) || (data_rs1 < 2'b00 && data_rs2 > 2'b00) || (data_rs1 < 2'b00 && data_rs2 < 2'b00) || (data_rs1 > 2'b00 && data_rs2 > 2'b00);
		end
		4'b1100: begin
			jmpb = (data_rs1 == data_rs2);
		end
		4'b1101: begin
			jmpb = (data_rs1 != data_rs2);
		end
		4'b1110: begin
			jmpb = (data_rs1 < data_rs2);
		end
		4'b1111: begin
			jmpb = (data_rs1 > data_rs2);
		end
		default: begin
			jmpb = 1'b0;
		end
	endcase
end

endmodule

