    parameter MODULO=6000000
)
(
    input input_clk,
    output output_clk
);
reg [WIDTH-1:0] counter;
    reg output_clk;
    initial
    begin
        output_clk = 0;
        counter = 0;
    end
    always @(posedge input_clk)
    begin
        if (counter == MODULO-1)
