module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0, cached_addr1;
reg [DW-1:0] cached_data0, cached_data1;
reg [21:0] subaddr;
reg [21:0] good;
reg hit0, hit1;

always @* begin
    addr_req = addr;
    if (DW == 8) begin
        addr_req = {addr_req, 2'b00};
    end else if (DW == 16) begin
        addr_req = {addr_req, 1'b0};
    end
    if (addr_ok) begin
        if (addr_req[AW-1:AW-2] == 2'b00) begin
            cached_addr0 = addr_req;
            cached_data0 = din;
            hit0 = 1'b1;
        end else if (addr_req[AW-1:AW-2] == 2'b01) begin
            cached_addr1 = addr_req;
            cached_data1 = din;
            hit1 = 1'b1;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst == 1'b1) begin
        sdram_addr <= 22'b0;
        data_ok <= 1'b0;
        req <= 1'b0;
        subaddr <= 22'b0;
        good <= 22'b0;
    end else if (clr == 1'b1) begin
        sdram_addr <= 22'b0;
        data_ok <= 1'b0;
        req <= 1'b0;
        subaddr <= 22'b0;
        good <= 22'b0;
    end else if (addr_ok == 1'b1) begin
        if (hit0 == 1'b0) begin
            sdram_addr <= {addr_req[AW-1:AW-2], 2'b00};
            data_ok <= 1'b1;
            req <= 1'b1;
            subaddr <= {addr_req[AW-1:AW-2], 2'b00};
            good <= {addr_req[AW-1:AW-2], 2'b00};
        end else if (hit1 == 1'b0) begin
            sdram_addr <= {addr_req[AW-1:AW-2], 2'b01};
            data_ok <= 1'b1;
            req <= 1'b1;
            subaddr <= {addr_req[AW-1:AW-2], 2'b01};
            good <= {addr_req[AW-1:AW-2], 2'b01};
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst == 1'b1) begin
        cached_addr0 <= 22'b0;
        cached_data0 <= 32'b0;
        cached_addr1 <= 22'b0;
        cached_data1 <= 32'b0;
    end else if (clr == 1'b1) begin
        cached_addr0 <= 22'b0;
        cached_data0 <= 32'b0;
        cached_addr1 <= 22'b0;
        cached_data1 <= 32'b0;
    end else if (we == 1'b1) begin
        if (addr_req[AW-1:AW-2] == 2'b00) begin
            cached_addr0 <= addr_req;
            cached_data0 <= din;
        end else if (addr_req[AW-1:AW-2] == 2'b01) begin
            cached_addr1 <= addr_req;
            cached_data1 <= din;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst == 1'b1) begin
        data_ok <= 1'b0;
    end else if (clr == 1'b1) begin
        data_ok <= 1'b0;
    end else if (req == 1'b1) begin
        if (addr_req[AW-1:AW-2] == 2'b00) begin
            data_ok <= 1'b1;
        end else if (addr_req[AW-1:AW-2] == 2'b01) begin
            data_ok <= 1'b1;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst == 1'b1) begin
        dout <= 32'b0;
    end else if (clr == 1'b1) begin
        dout <= 32'b0;
    end else if (req == 1'b1) begin
        if (addr_req[AW-1:AW-2] == 2'b00) begin
            dout <= cached_data0;
        end else if (addr_req[AW-1:AW-2] == 2'b01) begin
            dout <= cached_data1;
        end
    end
end

endmodule

