module mem_ctl(


    input wire clk,


    input wire [31:0]addr,

    input wire [31:0]data,


    input wire we,


    input wire [1:0]access_width
);
reg [31:0]data_reg;
    wire [31:0]data_masked;
    assign data_masked = data_reg & {access_width{1'b1}};
    always @(posedge clk) begin
        if(we) begin
            data_reg <= data;
            $display("data_reg = %b", data_reg);
            $display("data_masked = %b", data_masked);
        end
    end
    case(access_width)
        2'b00: begin
            data_reg <= data;
        end
        2'b01: begin
            data_reg <= {data[15:0],data[31:16]};
        end
        2'b10: begin
            data_reg <= {data[31:0],data[31:0]};
        end
    endcase
endmodule

