module regs(clock, reset, Rm, Rs, Rd, Rm_data, Rs_data, Rd_data);
	input clock, reset;
	input[4:0] Rm, Rs, Rd;
	output[31:0] Rm_data, Rs_data;
	input[31:0] Rd_data;
reg[31:0] regs[31];
	assign Rm_data = regs[Rm];
	assign Rs_data = regs[Rs];
	initial begin
		regs[0..31] = 0;
	end
	always @(posedge clock) begin
		if (reset) begin
