module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
);
reg [6:0] nextY;
reg [2:0] nextD;
reg [2:0] nextA;
reg [2:0] nextWR;
reg [2:0] nextRD;
reg [2:0] nextCLK;
reg [2:0] nextRST;
always @(posedge CLK, posedge RST) begin
	if (RST == 1'b1) begin
		nextD <= 3'b000;
		nextA <= 3'b000;
		nextWR <= 3'b000;
		nextRD <= 3'b000;
		nextCLK <= 3'b000;
		nextRST <= 3'b000;
	end else begin
		nextD <= D;
		nextA <= A;
		nextWR <= WR;
		nextRD <= RD;
		nextCLK <= CLK;
		nextRST <= RST;
	end
end
always @(nextD, nextA, nextWR, nextRD, nextCLK, nextRST) begin
	if (nextCLK == 1'b1) begin
		if (nextRD == 1'b1) begin
			if (nextWR == 1'b1) begin
				nextY <= nextD;
			end else begin
				nextY <= nextY;
			end
		end else begin
			if (nextWR == 1'b1) begin
				nextY <= nextA;
			end else begin
				nextY <= nextY;
			end
		end
	end else begin
		nextY <= nextY;
	end
end
assign WCTRL = nextWR;
assign Y = nextY;
endmodule

