module parallel_if();
reg [3:0] counter;
    reg reset;
    reg enable;
    reg up_en;
    reg down_en;
    always @(posedge clock)
    begin
        if(reset == 1'b1)
            counter <= 4'b0000;
        else if(enable == 1'b1)
            if(up_en == 1'b1)
                counter <= counter + 1;
            else if(down_en == 1'b1)
                counter <= counter - 1;
    end
endmodule

