module radix2(
		input wire [1:0] state,
		input wire signed [23:0] din_a_r,
		input wire signed [23:0] din_a_i,
		input wire signed [23:0] din_b_r,
		input wire signed [23:0] din_b_i,
		input wire signed [23:0] w_r,
		input wire signed [23:0] w_i,
		output reg signed[23:0] op_r,
		output reg signed[23:0] op_i,
		output reg signed[23:0] delay_r,
		output reg signed[23:0] delay_i,
		output reg outvalid
	);
reg [41:0] a_r;
	reg [41:0] a_i;
	reg [41:0] b_r;
	reg [41:0] b_i;
	reg [41:0] w_r_r;
	reg [41:0] w_r_i;
	reg [41:0] w_i_r;
	reg [41:0] w_i_i;
	reg [41:0] a_r_r;
	reg [41:0] a_r_i;
	reg [41:0] a_i_r;
	reg [41:0] a_i_i;
	reg [41:0] b_r_r;
	reg [41:0] b_r_i;
	reg [41:0] b_i_r;
	reg [41:0] b_i_i;
	reg [41:0] w_r_r_r;
	reg [41:0] w_r_r_i;
	reg [41:0] w_r_i_r;
	reg [41:0] w_r_i_i;
	reg [41:0] w_i_r_r;
	reg [41:0] w_i_r_i;
	reg [41:0] w_i_i_r;
	reg [41:0] w_i_i_i;
	always @(posedge state) begin
		case(state)
			2'b00: begin
				outvalid <= 0;
			end
			2'b01: begin
				outvalid <= 0;
			end
			2'b10: begin
				outvalid <= 0;
			end
			2'b11: begin
				outvalid <= 1;
			end
		endcase
	end
	always @(posedge state) begin
		case(state)
			2'b00: begin
				op_r <= 0;
				op_i <= 0;
			end
			2'b01: begin
				op_r <= (din_a_r + din_b_r) - (din_a_i - din_b_i);
				op_i <= (din_a_r - din_b_r) + (din_a_i + din_b_i);
			end
			2'b10: begin
				a_r <= (din_a_r + din_b_r) - (din_a_i - din_b_i);
				a_i <= (din_a_r - din_b_r) + (din_a_i + din_b_i);
				w_r_r <= (w_r + w_r) - (w_i - w_i);
				w_r_i <= (w_r - w_r) + (w_i + w_i);
				w_i_r <= (w_r + w_r) - (w_i - w_i);
				w_i_i <= (w_r - w_r) + (w_i + w_i);
				w_r_r_r <= (w_r_r + w_r_r) - (w_i_r - w_i_r);
				w_r_r_i <= (w_r_r - w_r_r) + (w_i_r + w_i_r);
				w_r_i_r <= (w_r_r + w_r_r) - (w_i_r - w_i_r);
				w_r_i_i <= (w_r_r - w_r_r) + (w_i_r + w_i_r);
				w_i_r_r <= (w_r_r + w_r_r) - (w_i_r - w_i_r);
				w_i_r_i <= (w_r_r - w_r_r) + (w_i_r + w_i_r);
				w_i_i_r <= (w_r_r + w_r_r) - (w_i_r - w_i_r);
				w_i_i_i <= (w_r_r - w_r_r) + (w_i_r + w_i_r);
				delay_r <= a_r_r;
				delay_i <= a_i_r;
			end
			2'b11: begin
				op_r <= a_r_r;
				op_i <= a_i_r;
			end
		endcase
	end
endmodule

module AMSG_kirsch_e(
  input [7:0] p1, p2, p3, p4, p6, p7, p8, p9,
  output reg [7:0] y1
    );
assign sum1 = p1 + p2 + p3 + p4;
  assign sum2 = p6 + p7 + p8 + p9;
  assign sum3 = sum1 - sum2;
  assign y1 = sum3 < 0 ? 0 : sum3 > 255 ? 255 : sum3;
endmodule

