module pingpongmem(clk, rst, wren, rden, address1, address2,
                    datain, dataout, inputsize);
input clk,rst;
input wren, rden;
input [31:0] inputsize;
input [31:0] address1, address2;

input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [16*16-1:0] datainmem, dataoutmem;
reg [64*16-1:0] datamem [0:1023];

always @(posedge clk) begin
    if(rst) begin
        datainmem <= 0;
        dataoutmem <= 0;
        for (int i = 0; i < 1024; i = i + 1) begin
            datamem[i] <= 0;
        end
    end else begin
        if(wren) begin
            datainmem <= datain[16*16-1:0];
            for (int i = 0; i < inputsize; i = i + 1) begin
                datamem[address1 + i] <= datain[16*16-1-16*i:16*i];
            end
        end
        if(rden) begin
            dataoutmem <= datamem[address2 + 16*16-1:16*16*address2];
        end
    end
end

assign dataout = dataoutmem[16*16-1:0];
endmodule

