module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] Divisor, Divider, remainder, result;
reg [31:0] counter;
reg done = 0;
initial
begin
	Divisor = 0;
	Divider = 0;
	remainder = 0;
	result = 0;
	counter = 0;
end
always @(posedge CLK)
begin
	if(done == 1)
	begin
		Divisor = 0;
		Divider = 0;
		remainder = 0;
		result = 0;
		counter = 0;
		done = 0;
	end
	else
	begin
		if(Divisor == 0)
		begin
			Divisor = Divisor;
			Divider = Divider;
			remainder = remainder;
			result = result;
			counter = counter;
			done = 0;
		end
		else
		begin
			if(Divisor > 0)
			begin
				if(Divisor > remainder)
				begin
					Divisor = Divisor - Divider;
					remainder = remainder - Divisor;
					result = result + 1;
					counter = counter + 1;
				end
				else
				begin
					Divisor = 0;
					Divider = 0;
					remainder = 0;
					result = result;
					counter = 0;
					done = 1;
				end
			end
			else
			begin
				Divisor = 0;
				Divider = 0;
				remainder = 0;
				result = result;
				counter = 0;
				done = 1;
			end
		end
	end
end
endmodule

