module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );
reg [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

    always @* begin
        a0 = a + b + c + d + m0;
        a1 = a0[63 : 32] ^ a0[31 : 0];
        b0 = a1[63 : 32] ^ a1[31 : 0];
        b1 = b0[63 : 32] ^ b0[31 : 0];
        b2 = b1[63 : 32] ^ b1[31 : 0];
        b3 = b2[63 : 32] ^ b2[31 : 0];
        c0 = b3[63 : 32] ^ b3[31 : 0];
        c1 = c0[63 : 32] ^ c0[31 : 0];
        d0 = c1[63 : 32] ^ c1[31 : 0];
        d1 = d0[63 : 32] ^ d0[31 : 0];
        d2 = d1[63 : 32] ^ d1[31 : 0];
        d3 = d2[63 : 32] ^ d2[31 : 0];
        a_prim = d3;
        b_prim = d2;
        c_prim = d1;
        d_prim = d0;
    end

endmodule

