      default: match <= 1'b0;
    endcase
  end
  always @(posedge rst) begin
    match <= 1'b0;
  end
endmodule

module complexmulttrial(
input [15:0] a_r,
input [15:0] a_i,
input [15:0] b_r,
input [15:0] b_i,
input [15:0] w_r,
input [15:0] w_i,
output [15:0] x_r,
output [15:0] x_i,
output [15:0] y_r,
output [15:0] y_i);
wire [31:0] a_r1 = a_r + a_r;
wire [31:0] a_i1 = a_i + a_i;
wire [31:0] b_r1 = b_r + b_r;
wire [31:0] b_i1 = b_i + b_i;
wire [31:0] w_r1 = w_r + w_r;
wire [31:0] w_i1 = w_i + w_i;
wire [31:0] a_r2 = a_r - a_r;
wire [31:0] a_i2 = a_i - a_i;
wire [31:0] b_r2 = b_r - b_r;
wire [31:0] b_i2 = b_i - b_i;
wire [31:0] w_r2 = w_r - w_r;
wire [31:0] w_i2 = w_i - w_i;
wire [31:0] a_r3 = a_r1 * a_r2;
wire [31:0] a_i3 = a_i1 * a_i2;
wire [31:0] b_r3 = b_r1 * b_r2;
wire [31:0] b_i3 = b_i1 * b_i2;
wire [31:0] w_r3 = w_r1 * w_r2;
wire [31:0] w_i3 = w_i1 * w_i2;
wire [31:0] a_r4 = a_r3 - a_r3;
wire [31:0] a_i4 = a_i3 - a_i3;
wire [31:0] b_r4 = b_r3 - b_r3;
wire [31:0] b_i4 = b_i3 - b_i3;
wire [31:0] w_r4 = w_r3 - w_r3;
wire [31:0] w_i4 = w_i3 - w_i3;
wire [31:0] a_r5 = a_r4 * a_r4;
wire [31:0] a_i5 = a_i4 * a_i4;
wire [31:0] b_r5 = b_r4 * b_r4;
wire [31:0] b_i5 = b_i4 * b_i4;
wire [31:0] w_r5 = w_r4 * w_r4;
wire [31:0] w_i5 = w_i4 * w_i4;
assign x_r = a_r5[31:16] + a_i5[15:0];
assign x_i = a_r5[31:16] - a_i5[15:0];
assign y_r = b_r5[31:16] + b_i5[15:0];
assign y_i = b_r5[31:16] - b_i5[15:0];
endmodule

