module UP_COUNTER #( parameter INIT_VALUE = 4'b0) (
	input wire       Reset,
	input wire       clock,
	output reg [3:0] Q
);
always @(posedge clock) begin
	if (Reset == 1'b1) begin
		Q <= INIT_VALUE;
	end else begin
		Q <= Q + 1;
	end
end
endmodule

module itg_lib1_gnc_init (
        ap_start,
        ap_done,
        ap_idle,
        ap_ready,
        p_p,
        ap_return,
        ap_rst
);







input   ap_start;
output   ap_done;
output   ap_idle;
output   ap_ready;
input  [7:0] p_p;
output  [31:0] ap_return;
input   ap_rst;
reg   ap_done;
reg   ap_idle;
reg   ap_ready;
reg   ap_start;







always @(posedge ap_start or posedge ap_rst) begin
    if (ap_rst == 1'b1) begin
        ap_done <= 1'b0;
        ap_idle <= 1'b0;
        ap_ready <= 1'b0;
    end else begin
        ap_done <= 1'b1;
        ap_idle <= 1'b0;
        ap_ready <= 1'b1;
    end
end

endmodule

