input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] mem [0:31];
initial
begin
    for (int i = 0; i < 32; i = i + 1)
    begin
        mem[i] = 0;
    end
end
always @(posedge clk)
begin
    if (MemWrite)
    begin
        mem[addr] <= write_data;
    end
end
assign read_data = MemRead ? mem[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
wire [BITS - 1:0] enable_wires;
assign enable_wires = {BITS - 1{ena}};
always @(posedge clk, posedge rst) begin
    if (rst) begin
        cnt <= 0;
    end else begin
        if (enable_wires[0]) begin
            cnt[0] <= cnt[0] + updown;
        end
        for (int i = 1; i < BITS; i = i + 1) begin
            if (enable_wires[i]) begin
                cnt[i] <= cnt[i - 1] + updown;
            end
        end
    end
end
assign out = cnt;
assign ovf = (cnt == 2**BITS - 1) ^ (cnt == 0);
endmodule

