module Divider #(parameter Time=20)
(
    input I_CLK,
    output reg O_CLK
);
reg [31:0] counter;
    initial
    begin
        O_CLK = 0;
    end
    always @(posedge I_CLK)
    begin
        if(counter == Time/2)
        begin
            O_CLK = ~O_CLK;
            counter = 0;
        end
        else if(counter == Time/2 - 1)
        begin
            O_CLK = 1;
            counter = 0;
        end
        else
        begin
            counter = counter + 1;
        end
    end
endmodule

