			end else if (sigma == 32'h80000000) begin
				delta <= 32'h0;
			end else begin
				delta <= 32'h1;
			end
		end
	end

	always @(posedge clk) begin
		if (rstn == 1'b0) begin
			deriv <= 32'h0;
		end else begin
			if (sigma == 32'h7fffffff) begin
				deriv <= 32'h0;
			end else if (sigma == 32'h80000000) begin
				deriv <= 32'h0;
			end else begin
				deriv <= sigma - undersampled_sigma;
			end
		end
	end

	always @(posedge clk) begin
		if (rstn == 1'b0) begin
			dout <= 32'h0;
		end else begin
			if (signed_data == 1'b1) begin
				dout <= {deriv[31:0], 1'b0};
			end else begin
				dout <= {deriv[31:0], 1'b1};
			end
		end
	end

endmodule

