module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0]state;
reg [SIZE-1:0]toggle;

initial
begin
	state = Zeros;
	toggle = Zeros;
end

always @(posedge clk or posedge reset)
begin
	if (reset == 1'b1)
		state = Zeros;
	else
		if (enable == 1'b1)
			state = {state[SIZE-2:0], ~state[SIZE-1]};
end

always @(state)
begin
	toggle[0] = 1'b1;
	toggle[1] = state[SIZE-2] ^ state[SIZE-1];
	toggle[2] = state[SIZE-3] ^ state[SIZE-2] ^ state[SIZE-1];
	toggle[3] = state[SIZE-4] ^ state[SIZE-3] ^ state[SIZE-2] ^ state[SIZE-1];
end

assign gray_out = state[SIZE-1:0];

endmodule

