module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0] ZERO = 2'b00;
    localparam [1:0] ONE = 2'b01;
    localparam [1:0] TWO = 2'b10;

    reg [1:0] state = ZERO;
    reg [N-1:0] data_p1 = 0;
    reg [N-1:0] data_p2 = 0;
    reg load_p1 = 0;
    reg load_p2 = 0;
    reg load_p1_from_p2 = 0;

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 0;
            data_p2 <= 0;
            load_p1 <= 0;
            load_p2 <= 0;
            load_p1_from_p2 <= 0;
        end else begin
            if (s_valid && s_ready && m_ready) begin
                if (state == ZERO) begin
                    state <= ONE;
                    data_p1 <= s_data;
                    load_p1 <= 1;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                end else if (state == ONE) begin
                    state <= TWO;
                    data_p2 <= s_data;
                    load_p1 <= 0;
                    load_p2 <= 1;
                    load_p1_from_p2 <= 0;
                end else if (state == TWO) begin
                    state <= ZERO;
                    data_p1 <= data_p2;
                    load_p1 <= 0;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            m_data <= 0;
            m_valid <= 0;
        end else begin
            if (load_p1_from_p2) begin
                m_data <= data_p1;
                m_valid <= 1;
            end else begin
                m_data <= data_p2;
                m_valid <= 0;
            end
        end
    end

    assign s_ready = m_ready;

    assign m_data = data_p1;
    assign m_valid = load_p1;

endmodule

module Incer #(
