output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg state;
parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case(state)
            ADD_STATE: begin
                if(mode)
                    counter <= counter + 1;
                else
                    counter <= counter + 2;
                if(mode)
                    state <= INC_STATE;
                else
                    state <= ADD_STATE;
            end
            INC_STATE: begin
                counter <= counter + 1;
                if(mode)
                    state <= ADD_STATE;
                else
                    state <= INC_STATE;
            end
        endcase
    end
end

assign dout = counter;

endmodule

