    output Y
);
reg Y_reg;
    always @(D0, D1, D2, D3, A, B) begin
        if (EN_n == 1'b0) begin
            Y_reg <= 1'b0;
        end else begin
            case (2'b00 + {A, B})
                2'b00: Y_reg <= D0;
                2'b01: Y_reg <= D1;
                2'b10: Y_reg <= D2;
                2'b11: Y_reg <= D3;
            endcase
        end
    end
    assign Y = Y_reg;
endmodule

