module main(
    input X4,
    input X3,
    input X2,
    input X1,
    input X0,
    output F
    );
assign F = X2 & (X3 & (X4 & (X1 & (X0 & (~X0)))))) | (~X2 & (X3 & (X4 & (X1 & (X0 & (~X1))))));
endmodule

module binary_to_BCD_ten_bit_tb;
reg [9:0] in;
wire [3:0] ones;
wire [3:0] tens;
wire [3:0] hundreds;
wire [0:0] thousands;

binary_to_BCD_ten_bit uut(
    .in(in),
    .ones(ones),
    .tens(tens),
    .hundreds(hundreds),
    .thousands(thousands)
);

initial begin
    in = 0;
    #1;
    forever begin
        in = in + 1;
        #1;
        $display("Input: %d, Ones: %d, Tens: %d, Hundreds: %d, Thousands: %d", in, ones, tens, hundreds, thousands);
    end
end

endmodule

module FullAdder(
  input wire a, 
  input wire b,
  input wire carry_in,
  output wire sum,
  output wire carry_out
);
assign sum = a ^ b;
  assign carry_out = (a & b) | (carry_in & sum);
endmodule

module AOI31X1TS (Y, A0, A1, A2, B0);
output Y;
input A0, A1, A2, B0;
specify
( (B0 -=> Y) = (0:0:0));
( (A0 -=> Y) = (0:0:0));
( (A1 -=> Y) = (0:0:0));
( (A2 -=> Y) = (0:0:0));
endspecify
and (Y, B0, A0, A1, A2);
nor (Y, B0, A0, A1, A2);
endmodule

