module p_adder #(parameter N=8) (
	input [N-1:0] A, B,
	input Cin,
	output [N-1:0] S,
	output Cout
	);
assign Cout = A[N-1] + B[N-1] + Cin;
	assign S = A + B + Cin;
endmodule

module display(
    input sysclk,
    input [7:0] anodes,
    output reg shift = 0,
    output reg latch = 0,
    output reg data = 0
    );
reg [1:0] step_count = 0;
    reg [7:0] anodes_reg = 0;
    always @(posedge sysclk) begin
        if (anodes_reg != anodes) begin
            step_count = 0;
            anodes_reg = anodes;
            latch = 1;
        end
        else begin
            if (step_count == 0) begin
                data = anodes_reg[0];
                shift = 1;
            end
            else if (step_count == 1) begin
                data = anodes_reg[1];
                shift = 1;
            end
            else if (step_count == 2) begin
                data = anodes_reg[2];
                shift = 1;
            end
            else if (step_count == 3) begin
                data = anodes_reg[3];
                shift = 1;
            end
            else if (step_count == 4) begin
                data = anodes_reg[4];
                shift = 1;
            end
            else if (step_count == 5) begin
                data = anodes_reg[5];
                shift = 1;
            end
            else if (step_count == 6) begin
                data = anodes_reg[6];
                shift = 1;
            end
            else if (step_count == 7) begin
                data = anodes_reg[7];
                shift = 1;
            end
            else if (step_count == 8) begin
                data = 0;
                shift = 0;
                latch = 0;
                step_count = 0;
            end
            else begin
                step_count = 0;
            end
        end
    end
endmodule

