module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg load_p1;
reg load_p2;
reg load_p1_from_p2;
reg [1:0] state;
reg [1:0] next;

assign s_ready = s_valid & m_ready;
assign m_data = data_p1;
assign m_valid = load_p1_from_p2;

always @(posedge clk or posedge reset) begin
    if (reset == 1'b1) begin
        data_p1 <= 0;
        data_p2 <= 0;
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                if (s_valid == 1'b1) begin
                    data_p1 <= s_data;
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                    state <= 2'b01;
                end
            end
            2'b01: begin
                if (s_valid == 1'b0) begin
                    data_p1 <= 0;
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                    state <= 2'b00;
                end
                else if (s_valid == 1'b1) begin
                    data_p1 <= s_data;
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                    state <= 2'b01;
                end
            end
            2'b10: begin
                if (s_valid == 1'b0) begin
                    data_p1 <= 0;
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                    state <= 2'b00;
                end
                else if (s_valid == 1'b1) begin
                    data_p1 <= s_data;
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                    state <= 2'b01;
                end
            end
            default: begin
                data_p1 <= 0;
                load_p1 <= 1'b0;
                load_p2 <= 1'b0;
                load_p1_from_p2 <= 1'b0;
                state <= 2'b00;
            end
        endcase
    end
end

always @(posedge clk or posedge reset) begin
    if (reset == 1'b1) begin
        next <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                next <= 2'b01;
            end
            2'b01: begin
                next <= 2'b10;
            end
            2'b10: begin
                next <= 2'b00;
            end
            default: begin
                next <= 2'b00;
            end
        endcase
    end
end

endmodule

