module lfsr24(
input wire Clk,
input wire one,
input wire tick,
input wire [6:0] coreCount,
output reg data
); 

reg [23:0] lfsr_p;
reg [23:0] lfsr_n;
  always @(posedge Clk) begin
    if (one == 1'b1) begin
      lfsr_p <= 24'h020000;
    end else begin
      if (tick == 1'b1) begin
        lfsr_p <= lfsr_n;
      end
    end
  end
  always @(posedge Clk) begin
    if (one == 1'b1) begin
      lfsr_n <= 24'h020000;
    end else begin
      if (tick == 1'b1) begin
        lfsr_n <= lfsr_p;
      end
      if (coreCount < 24) begin
        lfsr_n <= {lfsr_p[22], lfsr_p[23], lfsr_p[19], lfsr_p[18], lfsr_p[17], lfsr_p[16], lfsr_p[15], lfsr_p[14], lfsr_p[13], lfsr_p[12], lfsr_p[11], lfsr_p[10], lfsr_p[9], lfsr_p[8], lfsr_p[7], lfsr_p[6], lfsr_p[5], lfsr_p[4], lfsr_p[3], lfsr_p[2], lfsr_p[1], lfsr_p[0]};
      end
    end
  end
  assign data = lfsr_p[coreCount];
endmodule

