module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [3:0] counter;
    reg [7:0] shift_reg;
    always @(posedge clk, negedge rst_n) begin
        if(!rst_n) begin
            dout_parallel <= 8'b0;
            dout_valid <= 0;
            counter <= 4'b0;
        end else begin
            if(din_valid) begin
                shift_reg <= {shift_reg[6:0], din_serial};
                counter <= counter + 1;
                if(counter == 4'b100) begin
                    dout_parallel <= shift_reg;
                    dout_valid <= 1;
                    counter <= 4'b0;
                end
            end
        end
    end
endmodule

module Bin7SegDecoder(
input wire [3:0] binInput,
output reg [6:0] decOut_n
); 

always @(binInput) begin
    case(binInput)
      4'b0001 : decOut_n <= 7'b0000001;
      4'b0010 : decOut_n <= 7'b1001111;
      4'b0100 : decOut_n <= 7'b0010010;
      4'b0110 : decOut_n <= 7'b0000110;
      4'b1000 : decOut_n <= 7'b0100001;
      4'b1010 : decOut_n <= 7'b0000000;
      4'b1100 : decOut_n <= 7'b0000100;
      4'b1110 : decOut_n <= 7'b0001000;
      default : decOut_n <= 7'b1000000;
    endcase
  end
endmodule

