module pe(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] c
);
wire [63:0] product;
    assign product = a * b;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            c <= 0;
        end else begin
            c <= c + product[31:0];
        end
    end
endmodule

module testbench;
reg [2:0] A, B;
wire A_greater, A_equal, A_less;
comparator_3bit comp(A, B, A_greater, A_equal, A_less);

initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, testbench);
    $display("Starting testbench");
    for (i = 0; i < 100; i = i + 1) begin
        A = $random;
        B = $random;
        if (A > B) begin
            if (!A_greater) begin
                $display("Test failed at iteration %d: A > B, but A_greater is not set", i);
                error = error + 1;
            end
        end else if (A < B) begin
            if (!A_less) begin
                $display("Test failed at iteration %d: A < B, but A_less is not set", i);
                error = error + 1;
            end
        end else if (A == B) begin
            if (!A_equal) begin
                $display("Test failed at iteration %d: A == B, but A_equal is not set", i);
                error = error + 1;
            end
        end else begin
            $display("Test failed at iteration %d: unexpected comparison result", i);
            error = error + 1;
        end
    end
    if (error == 0) begin
        $display("Test passed");
    end else begin
        $display("Test failed with %d errors", error);
    end
end

endmodule

