   input wren; 
   input[addr_width - 1:0] wraddress; 
   input[addr_width - 1:0] rdaddress; 
   input wrclock; 
   input rdclock; 
   output[data_width - 1:0] q;
parameter data_width = 32; 
   parameter addr_width = 16; 
   reg[data_width - 1:0] mem[2**addr_width - 1:0]; 
   reg[addr_width - 1:0] wraddress_reg; 
   reg[addr_width - 1:0] rdaddress_reg; 
   reg wren_reg; 
   reg[addr_width - 1:0] wraddress_reg_next; 
   reg[addr_width - 1:0] rdaddress_reg_next; 
   reg wren_reg_next; 
   always @(posedge wrclock) begin
      wraddress_reg <= wraddress; 
      wren_reg <= wren; 
   end
   always @(posedge rdclock) begin
      rdaddress_reg <= rdaddress; 
      wren_reg_next <= wren_reg; 
      wraddress_reg_next <= wraddress_reg; 
   end
   always @(posedge wrclock) begin
      if (wren_reg) begin
         mem[wraddress_reg] <= data; 
      end
   end
   always @(posedge rdclock) begin
      if (wren_reg_next) begin
         wraddress_reg_next <= wraddress_reg_next; 
      end
      else begin
         wraddress_reg_next <= wraddress_reg; 
      end
   end
   always @(posedge rdclock) begin
      if (wren_reg_next) begin
         rdaddress_reg_next <= rdaddress_reg_next; 
      end
      else begin
         rdaddress_reg_next <= rdaddress_reg; 
      end
   end
   always @(posedge rdclock) begin
      if (wren_reg_next) begin
         wren_reg_next <= wren_reg_next; 
      end
      else begin
         wren_reg_next <= wren_reg; 
      end
   end
