module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;

    initial begin
        if (lpm_width <= 0) begin
            $display("ERROR: lpm_width must be greater than zero");
            $finish;
        end
        if (lpm_size <= 0) begin
            $display("ERROR: lpm_size must be greater than zero");
            $finish;
        end
    end


    reg [(lpm_size * lpm_width)-1:0] result;

    always @(*) begin
        for (int i = 0; i < lpm_size; i = i + 1) begin
            result[i * lpm_width + :lpm_width] = 0;
            for (int j = 0; j < lpm_width; j = j + 1) begin
                result[i * lpm_width + :lpm_width] = result[i * lpm_width + :lpm_width] | data[i * lpm_width + j];
            end
        end
        result = result;
    end


endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg [1:0] cnt;
    reg clk_div;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else begin
            if(cnt == NUM_DIV - 1) begin
                cnt <= 0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

