	input	clk,
   input pulse,
   output o_pwm
);
reg [8:0] PWM_accumulator;
   reg [1:0] state;
   always @(posedge clk) begin
      case(state)
         0: begin
            if(pulse) begin
               PWM_accumulator <= PWM_accumulator + 255;
               if(PWM_accumulator[8] == 1'b1) begin
                  o_pwm <= 1'b1;
               end
               else begin
                  o_pwm <= 1'b0;
               end
            end
            else begin
               o_pwm <= 1'b0;
            end
         end
         1: begin
            PWM_accumulator <= PWM_accumulator + 255;
            if(PWM_accumulator[8] == 1'b1) begin
               o_pwm <= 1'b1;
            end
            else begin
               o_pwm <= 1'b0;
            end
         end
      endcase
      if(state == 0) begin
         state <= 1;
      end
      else begin
         state <= 0;
      end
   end
endmodule

