module zsignals
(
  input wire clk,
  input wire zpos,
  input wire rst_n,
  input wire iorq_n,
  input wire mreq_n,
  input wire m1_n,
  input wire rfsh_n,
  input wire rd_n,
  input wire wr_n,
  output wire rst,
  output wire m1,
  output wire rfsh,
  output wire rd,
  output wire wr,
  output wire iorq,
  output wire mreq,
  output wire rdwr,
  output wire iord,
  output wire iowr,
  output wire iordwr,
  output wire memrd,
  output wire memwr,
  output wire memrw,
  output wire opfetch,
  output wire intack,
  output wire iorq_s,
  output wire mreq_s,
  output wire iord_s,
  output wire iowr_s,
  output wire iordwr_s,
  output wire memrd_s,
  output wire memwr_s,
  output wire memrw_s,
  output wire opfetch_s
);
reg [1:0] iorq;
  reg [1:0] mreq;
  reg [1:0] iord;
  reg [1:0] iowr;
  reg [1:0] iordwr;
  reg [1:0] memrd;
  reg [1:0] memwr;
  reg [1:0] memrw;
  reg [1:0] opfetch;
  reg [1:0] intack;
  reg [1:0] iorq_s;
  reg [1:0] mreq_s;
  reg [1:0] iord_s;
  reg [1:0] iowr_s;
  reg [1:0] iordwr_s;
  reg [1:0] memrd_s;
  reg [1:0] memwr_s;
  reg [1:0] memrw_s;
  reg [1:0] opfetch_s;
  always @(posedge clk)
    begin
      if (!rst_n)
        begin
          iorq <= 2'b00;
          mreq <= 2'b00;
          iord <= 2'b00;
          iowr <= 2'b00;
          iordwr <= 2'b00;
          memrd <= 2'b00;
          memwr <= 2'b00;
          memrw <= 2'b00;
          opfetch <= 2'b00;
          intack <= 2'b00;
        end
      else
        begin
          if (zpos)
            begin
              iorq <= 2'b01;
              mreq <= 2'b01;
              iord <= 2'b01;
              iowr <= 2'b01;
              iordwr <= 2'b01;
              memrd <= 2'b01;
              memwr <= 2'b01;
              memrw <= 2'b01;
              opfetch <= 2'b01;
              intack <= 2'b01;
            end
          else
            begin
              iorq <= 2'b00;
              mreq <= 2'b00;
              iord <= 2'b00;
              iowr <= 2'b00;
              iordwr <= 2'b00;
              memrd <= 2'b00;
              memwr <= 2'b00;
              memrw <= 2'b00;
              opfetch <= 2'b00;
              intack <= 2'b00;
            end
        end
    end
  always @(posedge clk)
    begin
      if (!rst_n)
        begin
          iorq_s <= 2'b00;
          mreq_s <= 2'b00;
          iord_s <= 2'b00;
          iowr_s <= 2'b00;
          iordwr_s <= 2'b00;
          memrd_s <= 2'b00;
          memwr_s <= 2'b00;
          memrw_s <= 2'b00;
          opfetch_s <= 2'b00;
          intack_s <= 2'b00;
        end
      else
        begin
          iorq_s <= iorq;
          mreq_s <= mreq;
          iord_s <= iord;
          iowr_s <= iowr;
          iordwr_s <= iordwr;
          memrd_s <= memrd;
          memwr_s <= memwr;
          memrw_s <= memrw;
          opfetch_s <= opfetch;
          intack_s <= intack;
        end
    end
  assign rst = iorq_s[0];
  assign m1 = mreq_s[0];
  assign rfsh = iord_s[0];
  assign rd = iord_s[1];
  assign wr = iowr_s[0];
  assign iorq = iorq_s[1];
  assign mreq = mreq_s[1];
  assign rdwr = iord_s[1] & iowr_s[1];
  assign iord = iord_s[1];
  assign iowr = iowr_s[1];
  assign iordwr = iord_s[1] & iowr_s[1];
  assign memrd = memrd_s[1];
  assign memwr = memwr_s[1];
  assign memrw = memrw_s[1];
  assign opfetch = opfetch_s[1];
  assign intack = intack_s[1];
endmodule

