module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
reg [4:0] state;
reg [31:0] PWDATA;
reg [31:0] read_data;
reg [31:0] write_data;
reg [31:0] PRDATA;
reg PSELx;
reg PENABLE;
reg PWRITE;
reg PREADY;
reg PSLVERR;
reg Transfer;
reg Wr_Rd;
reg [4:0] Address;
initial
begin
    state = IDLE;
    PSELx = 0;
    PENABLE = 0;
    PWRITE = 0;
    PADDR = 0;
    PWDATA = 0;
    read_data = 0;
    write_data = 0;
    PRDATA = 0;
end
always @(posedge PCLK)
begin
    if (PRESETn == 0)
    begin
        state <= IDLE;
        PSELx <= 0;
        PENABLE <= 0;
        PWRITE <= 0;
        PADDR <= 0;
        PWDATA <= 0;
        read_data <= 0;
        write_data <= 0;
        PRDATA <= 0;
    end
    else
    begin
        case (state)
        IDLE: begin
            if (Transfer == 1)
            begin
                PSELx <= 1;
                PENABLE <= 1;
                PWRITE <= Wr_Rd;
                PADDR <= Address;
                PWDATA <= write_data;
                state <= SETUP;
            end
        end
        SETUP: begin
            if (PREADY == 1)
            begin
                PSELx <= 0;
                PENABLE <= 0;
                PWRITE <= 0;
                PADDR <= 0;
                PWDATA <= 0;
                state <= ACCESS;
            end
        end
        ACCESS: begin
            if (PSLVERR == 1)
            begin
                PSELx <= 0;
                PENABLE <= 0;
                PWRITE <= 0;
                PADDR <= 0;
                PWDATA <= 0;
                state <= IDLE;
            end
            else if (Transfer == 1)
            begin
                PSELx <= 1;
                PENABLE <= 1;
                PWRITE <= Wr_Rd;
                PADDR <= Address;
                PWDATA <= write_data;
                state <= SETUP;
            end
            else if (Wr_Rd == 1)
            begin
                PSELx <= 1;
                PENABLE <= 1;
                PWRITE <= Wr_Rd;
                PADDR <= Address;
                PWDATA <= write_data;
                state <= SETUP;
            end
            else if (Wr_Rd == 0)
            begin
                PSELx <= 1;
                PENABLE <= 1;
                PWRITE <= Wr_Rd;
                PADDR <= Address;
                PWDATA <= write_data;
                state <= SETUP;
            end
        end
        default: begin
            PSELx <= 0;
            PENABLE <= 0;
            PWRITE <= 0;
            PADDR <= 0;
            PWDATA <= 0;
            state <= IDLE;
        end
        endcase
    end
end
endmodule

