module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [31:0] maxValue;
reg [31:0] inDataBuffer [numInput-1:0];
reg [31:0] counter;
always @(posedge i_clk) begin
    if(i_valid) begin
        counter <= 0;
        maxValue <= inDataBuffer[0];
        o_data_valid <= 0;
    end else begin
        if(counter == 0) begin
            maxValue <= inDataBuffer[0];
            o_data_valid <= 0;
        end else begin
            if(inDataBuffer[counter-1] > maxValue) begin
                maxValue <= inDataBuffer[counter-1];
                o_data <= counter-1;
                o_data_valid <= 1;
            end else begin
                o_data <= o_data;
                o_data_valid <= 0;
            end
        end
        counter <= counter + 1;
    end
end
endmodule

