module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter g_Clock_Frequency = 100000000;
parameter g_Initial_Reset_Time = 1000000;
reg r_RST;
reg r_RST_Counter;
integer c_Initial_Reset_Clocks;
initial begin
    c_Initial_Reset_Clocks = g_Clock_Frequency * g_Initial_Reset_Time;
end
always @(posedge i_CLK) begin
    if (r_RST_Counter == c_Initial_Reset_Clocks) begin
        r_RST <= 0;
    end else begin
        r_RST <= 1;
        r_RST_Counter <= r_RST_Counter + 1;
    end
end
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [31:0] timeCount = 0;
reg [31:0] timeoutCounter = 0;
reg [1:0] state = 0;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        timeCount <= 0;
        timeoutCounter <= 0;
        state <= 0;
        sonar_trigger <= 0;
        inches <= 0;
        READY <= 0;
    end else begin
        case(state)
            0: begin
                if(do_measure) begin
                    state <= 1;
                    sonar_trigger <= 1;
                end
            end
            1: begin
                if(sonar_pulse) begin
                    state <= 2;
                end
            end
            2: begin
                timeoutCounter <= timeoutCounter + 1;
                if(sonar_pulse) begin
                    timeoutCounter <= 0;
                    state <= 3;
                end
            end
            3: begin
                timeCount <= timeCount + 1;
                if(!sonar_pulse) begin
                    timeCount <= 0;
                    state <= 0;
                    inches <= timeCount / 58;
                    READY <= 1;
                end
            end
            default: begin
                state <= 0;
            end
        endcase
    end
end
endmodule

