module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg [63:0] value;
  reg [1:0] state;
  reg s_input_a_ack;
  initial
    begin
      state = 0;
      s_input_a_ack = 0;
    end
  always @(posedge clk)
    begin
      if (rst)
        begin
          state = 0;
          s_input_a_ack = 0;
        end
      else
        begin
          case (state)
            0: begin
              if (input_a_stb)
                begin
                  value = input_a;
                  state = 1;
                  s_input_a_ack = 1;
                end
              else
                begin
                  s_input_a_ack = 0;
                end
            end
            1: begin
              $fopena (fptr, "resp_z", "a");
              $fdisplay (fptr, "%d", value[31:0]);
              $fdisplay (fptr, "%d", value[63:32]);
              $fclose (fptr);
              state = 0;
              s_input_a_ack = 0;
            end
            default: begin
              s_input_a_ack = 0;
            end
          endcase
        end
    end
  assign input_a_ack = s_input_a_ack;
endmodule

