module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 16;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    always @(posedge clk) begin
        if (n_reset) begin
            q_reg <= 0;
            f1 <= 0;
            f2 <= 0;
        end else begin
            q_reg <= q_next;
            f1 <= button_in;
            f2 <= f1;
        end
    end
    always @(posedge clk) begin
        if (n_reset) begin
            q_next <= 0;
            q_add <= 0;
            q_reset <= 0;
        end else begin
            q_next <= q_reg;
            q_add <= q_reg == 0 ? f1 : 0;
            q_reset <= q_reg == 0 ? f2 : 0;
        end
    end
    always @(posedge clk) begin
        if (n_reset) begin
            out <= 0;
        end else if (q_reg == maxbit - 1) begin
            out <= f1;
        end
    end
endmodule

