module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [15 : 0];
    reg [7 : 0] wp, rp;
    reg w_flag, r_flag;
    always @(posedge clock) begin
        if(sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end else begin
            if(wrreq) begin
                if(w_flag) begin
                    wp <= 0;
                    w_flag <= 0;
                end else begin
                    wp <= wp + 1;
                    w_flag <= 1;
                end
            end
            if(rdreq) begin
                if(r_flag) begin
                    rp <= 0;
                    r_flag <= 0;
                end else begin
                    rp <= rp + 1;
                    r_flag <= 1;
                end
            end
        end
    end
    always @(posedge clock) begin
        if(w_flag) begin
            mem[wp] <= data;
        end
    end
    always @(posedge clock) begin
        if(r_flag) begin
            q <= mem[rp];
        end
    end
    assign full = (wp == rp) & w_flag;
    assign empty = (wp == rp) & ~w_flag;
endmodule

