module timer_variable(
input wire zedboard_clk,
input wire enable,
input wire reset,
output reg timerOutput
); 

reg [31:0] timer_value;
  always @(posedge zedboard_clk) begin
    if (reset == 1'b1) begin
      timer_value <= 32'h0;
      timerOutput <= 1'b0;
    end else if (timer_value == 32'h100000) begin
      timerOutput <= 1'b1;
      timer_value <= 32'h0;
    end else begin
      timerOutput <= 1'b0;
      timer_value <= timer_value + 1;
    end
  end
endmodule

module NAND3xp33_ASAP7_75t_R (Y, A, B, C);
output Y;
input A, B, C;
not (notB, B);
   not (notA, A);
   not (notC, C);
   or (Y, notA, notB, notC);
   specify
      specparam
         tplh$A$Y = 1.0,
         tphl$A$Y = 1.0,
         tplh$B$Y = 1.0,
         tphl$B$Y = 1.0,
         tplh$C$Y = 1.0,
         tphl$C$Y = 1.0;
   endspecify
endmodule

module dffrl_async (din, clk, rst_l, q, se, si, so);

input   [SIZE-1:0]      din ;   
input                   clk ;   
input                   rst_l ;   

output  [SIZE-1:0]      q ;     

input                   se ;    
input   [SIZE-1:0]      si ;    
output  [SIZE-1:0]      so ;
parameter SIZE = 16;

reg   [SIZE-1:0]      q ;     

always @(posedge clk or negedge rst_l) begin
    if (!rst_l)
        q <= 0;
    else
        q <= din;
end

endmodule

module TB_synchro;
reg clk;
    reg dato;
    wire ds;

    Synchro uut (dato, clk, ds);

    initial
    begin
        clk = 0;
        dato = 0;
        #20 clk = 1;
        dato = 1;
        #50 dato = 0;
        #50 $finish;
    end

    always
    begin
        #30 dato = 1;
        #50 dato = 0;
    end

endmodule

module sr_latch(NQ, Q, S, R);
output Q, NQ;
input S, R;
reg state = 1;
assign NQ = ~Q;
always @(posedge S, posedge R) begin
    if (S == 1'b1) begin
      state = 1'b1;
    end else if (R == 1'b1) begin
      state = 1'b0;
    end
  end
  assign #5 Q = state;
endmodule

