module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk) begin
        if (J & K) Q <= ~Q;
        else if (J) Q <= 1;
        else if (K) Q <= 0;
    end
    assign Qbar = ~Q;
endmodule

