module FSM_game(
input wire iRST,
input wire iCLK,
input wire [1:0] iA,
input wire [1:0] iB,
output wire oA,
output wire oB
);
parameter [1:0] sDRAW = 2'b00;
parameter [1:0] sB_LEAD = 2'b01;
parameter [1:0] sB_WIN = 2'b10;
parameter [1:0] sA_LEAD = 2'b11;
parameter [1:0] sA_WIN = 2'b11;
wire [1:0] sSTATE;
wire [1:0] sNEXT_STATE;
wire [1:0] sWIN;
assign oA = sWIN[0];
assign oB = sWIN[1];
assign sSTATE = sNEXT_STATE;
always @(posedge iCLK, posedge iRST) begin
    if (iRST == 1'b1) begin
        sNEXT_STATE <= sDRAW;
    end else begin
        case (sSTATE)
            sDRAW: begin
                if (iA == 2'b00 && iB == 2'b00) begin
                    sNEXT_STATE <= sDRAW;
                end else if (iA == 2'b00 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_LEAD;
                end else if (iA == 2'b01 && iB == 2'b00) begin
                    sNEXT_STATE <= sA_LEAD;
                end else if (iA == 2'b01 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_WIN;
                end else if (iA == 2'b10 && iB == 2'b00) begin
                    sNEXT_STATE <= sA_LEAD;
                end else if (iA == 2'b10 && iB == 2'b01) begin
                    sNEXT_STATE <= sA_WIN;
                end else if (iA == 2'b11 && iB == 2'b00) begin
                    sNEXT_STATE <= sB_LEAD;
                end else if (iA == 2'b11 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_WIN;
                end
            end
            sB_LEAD: begin
                if (iA == 2'b00 && iB == 2'b00) begin
                    sNEXT_STATE <= sDRAW;
                end else if (iA == 2'b00 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_LEAD;
                end else if (iA == 2'b01 && iB == 2'b00) begin
                    sNEXT_STATE <= sA_LEAD;
                end else if (iA == 2'b01 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_WIN;
                end
            end
            sB_WIN: begin
                sNEXT_STATE <= sB_WIN;
            end
            sA_LEAD: begin
                if (iA == 2'b00 && iB == 2'b00) begin
                    sNEXT_STATE <= sDRAW;
                end else if (iA == 2'b00 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_LEAD;
                end else if (iA == 2'b01 && iB == 2'b00) begin
                    sNEXT_STATE <= sA_LEAD;
                end else if (iA == 2'b01 && iB == 2'b01) begin
                    sNEXT_STATE <= sB_WIN;
                end
            end
            sA_WIN: begin
                sNEXT_STATE <= sA_WIN;
            end
            default: begin
                sNEXT_STATE <= sDRAW;
            end
        endcase
    end
end
endmodule

