    or or3 (alu_ctrl[2], alu_ctrl[2], alu_ctrl[0]);
    and and4 (alu_ctrl[0], alu_ctrl[0], func[0]);
    and and5 (alu_ctrl[1], alu_ctrl[1], func[1]);
    and and6 (alu_ctrl[2], alu_ctrl[2], func[2]);
    or or4 (alu_ctrl[0], alu_ctrl[0], alu_ctrl[1]);
