module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);
reg [3:0] Digit3_temp;
	reg [3:0] Digit2_temp;
	reg [3:0] Digit1_temp;
	reg [3:0] Digit0_temp;

	always @(Input)
	begin
		for (integer i = INPUT_BIT_WIDTH-1; i >= 0; i--)
		begin
			if (Digit3_temp >= 9)
				Digit3_temp = Digit3_temp + 3;
			if (Digit2_temp >= 9)
				Digit2_temp = Digit2_temp + 3;
			if (Digit1_temp >= 9)
				Digit1_temp = Digit1_temp + 3;
			if (Digit0_temp >= 9)
				Digit0_temp = Digit0_temp + 3;

			Digit3_temp = Digit3_temp << 1;
			Digit2_temp = Digit2_temp << 1;
			Digit1_temp = Digit1_temp << 1;
			Digit0_temp = Digit0_temp << 1;

			if (Input[i] == 1)
				Digit0_temp = Digit0_temp | 1;
		end
		Digit3 = Digit3_temp;
		Digit2 = Digit2_temp;
		Digit1 = Digit1_temp;
		Digit0 = Digit0_temp;
	end
endmodule

