module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 32;
parameter TOTAL_DAT = 32;
parameter SEL_WIDTH = 1;

wire [DAT_WIDTH-1:0] temp[2**SEL_WIDTH-1:0];

assign dout = temp[sel];

generate
for (int i = 0; i < 2**SEL_WIDTH; i = i + 1) begin
assign temp[i] = din[i*DAT_WIDTH:(i+1)*DAT_WIDTH-1];
end
endgenerate

endmodule

