module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
reg [counterSize-1:0] counts [numOfCounters-1:0];
   reg [numOfCounters-1:0] terminalCounts [numOfCounters-1:0];
   generate
      for (genvar i = 0; i < numOfCounters; i = i + 1) begin : gen
         NBitCounter #(
            .counterSize(counterSize)
         ) counter (
            .clk(clk),
            .reset(reset),
            .count(counts[i]),
            .enable(terminalCounts[i]),
            .outCount(counts[i+1])
         );
      end
   endgenerate
   assign outCount = counts[numOfCounters-1];
   assign terminalCounts[0] = 1'b0;
   always @(posedge clk) begin
      if (reset == 1'b1) begin
         for (genvar i = 0; i < numOfCounters; i = i + 1) begin : gen
            terminalCounts[i] <= 1'b0;
         end
      end else begin
         for (genvar i = 0; i < numOfCounters; i = i + 1) begin : gen
            terminalCounts[i] <= terminalCounts[i-1];
         end
      end
   end
endmodule

