module division(A,B,Res);
    input [WIDTH-1:0] A;
    input [WIDTH-1:0] B;

    output reg [WIDTH-1:0] Res = 0;
reg [WIDTH-1:0] a1;
    reg [WIDTH-1:0] b1;
    reg [16:0] p1;
    parameter WIDTH = 16;
    always @(A,B) begin
        for (int i=0;i<WIDTH;i=i+1) begin
            a1 = A;
            b1 = B;
            p1 = {17{1'b0}};
            for (int j=0;j<WIDTH;j=j+1) begin
                if (a1[WIDTH-1-j] == 1'b1) begin
                    p1 = p1 - b1;
                    a1 = a1 - b1;
                end
                a1 = a1 >> 1;
            end
            Res = a1;
        end
    end
endmodule

