module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
);
parameter [9:0] hsize = 1024;
parameter [9:0] vsize = 768;
parameter [9:0] hfront = 10;
parameter [9:0] hback = 10;
parameter [9:0] vfront = 10;
parameter [9:0] vback = 10;
parameter [9:0] hretrace = 10;
parameter [9:0] vretrace = 10;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
wire [9:0] xaddr;
wire [9:0] yaddr;
always @(posedge clk) begin
    if (rst) begin
        h_count_reg <= 0;
        v_count_reg <= 0;
    end else begin
        h_count_reg <= h_count_reg + 1;
        v_count_reg <= v_count_reg + 1;
    end
end
assign xaddr = h_count_reg;
assign yaddr = v_count_reg;
assign active = (h_count_reg >= hfront) && (h_count_reg < (hsize - hback)) && (v_count_reg >= vfront) && (v_count_reg < (vsize - vback));
assign hsync = (h_count_reg >= (hsize - hretrace)) && (h_count_reg < (hsize - hfront));
assign vsync = (v_count_reg >= (vsize - vretrace)) && (v_count_reg < (vsize - vfront));
endmodule

