module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);
reg walk_left;
    reg walk_right;
    reg aaah;
    reg [1:0] state;
    reg [1:0] next_state;
    always @(posedge clk) begin
        if (arst) begin
            walk_left <= 1'b0;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            state <= 2'b00;
        end else begin
            walk_left <= next_state[0];
            walk_right <= next_state[1];
            aaah <= next_state[2];
            state <= next_state[3];
        end
    end
    always @(posedge clk) begin
        if (arst) begin
            next_state[0] <= 1'b0;
            next_state[1] <= 1'b0;
            next_state[2] <= 1'b0;
            next_state[3] <= 2'b00;
        end else begin
            next_state[0] <= walk_left;
            next_state[1] <= walk_right;
            next_state[2] <= aaah;
            next_state[3] <= state;
        end
    end
    assign walk_left = state[0];
    assign walk_right = state[1];
    assign aaah = state[2];
endmodule

