module TopModule(
    input  clock,
    input  a,
    output p,
    output q
);
reg p;
reg q;
always @(posedge clock) begin
    if (a == 1'b0) begin
        p <= 1'b0;
        q <= 1'b0;
    end else begin
        p <= 1'b1;
        q <= 1'b1;
    end
end
endmodule

module TopModule(
    input  clk,
    input  in,
    input  reset,
    output reg out_byte,
    output reg done
);
always @(posedge clk) begin
        if (reset) begin
            out_byte <= 0;
            done <= 0;
        end else begin
            if (in == 0) begin
                out_byte <= 0;
                done <= 0;
            end else if (in == 1) begin
                out_byte <= out_byte << 1;
                done <= 0;
            end else begin
                out_byte <= out_byte << 1;
                done <= 0;
            end
        end
    end
endmodule

